/* The dialogue's canonical home is before-the-law.html. Extract it rather than
   retyping it: the spec says do not rewrite the dialogue, and a second hand-typed
   copy is exactly how two versions drift apart. */
import fs from 'fs';
const src = fs.readFileSync('../before-the-law.html', 'utf8');
const a = src.indexOf('var T = {');
const b = src.indexOf('\n};', a);
if (a < 0 || b < 0) throw new Error('could not locate the T block in before-the-law.html');
const block = src.slice(a + 'var T = '.length, b + 3).replace(/;\s*$/, '');
fs.writeFileSync('../src/text.gen.js',
  '/* generated by tools/extract-text.mjs from before-the-law.html - do not edit */\nexport const T = ' + block + ';\n');
const T = (await import('../src/text.gen.js')).T;
const keys = Object.keys(T);
console.log('extracted', keys.length, 'blocks:', keys.join(' '));
let n = 0; for (const k of keys) n += Array.isArray(T[k][0]) ? T[k].flat().length : T[k].length;
console.log('total lines:', n);
